class Deadline(object):
  KEY = "__Deadline"
  EVENT_KEY = "__Deadline_Event"

  def __init__(self, timeout):
    """
    Args:
      timeout - The timeout in seconds
    """
    import  time
    self._ts = Long(time.time()) * 1000000000 # Nanoseconds
    self._timeout = Long(timeout * 1000000000)
scales/sink.py
class ClientMessageSink(MessageSink):
  """ClientMessageSinks take a message, stream, and headers and perform
  processing on them. """
  __slots__ = '_on_faulted',
  Role = None
  Builder = None

  def __init__(self):
    self._on_faulted = Observable()
    super(ClientMessageSink, self).__init__()

  @property
  def state(self):
    return self.next_sink.state

  @property
  def is_open(self):
    """Returns True if the sink is Idle, Open, or Busy"""
    return self.state <= ChannelState.Busy

  @property
  def is_closed(self):
    """Returns True if the sink is Closed."""
    return self.state == ChannelState.Closed

  @property
  def is_ready(self):
    """Returns True if the channel is open, eg ready to process messages."""
    return self.state == ChannelState.Open

  @property
  def on_faulted(self):
    return self._on_faulted

  def Open(self):
    if self.next_sink:
      return self.next_sink.Open()
    else:
      return AsyncResult.Complete()

  def Close(self):
    if self.next_sink:
      self.next_sink.Close()

  @abstractmethod
  def AsyncProcessRequest(self, sink_stack, msg, stream, headers):
    """Process a request message, stream, and headers. Args:
      sink_stack - The SinkStack representing the processing state of the message. How it would "walk" would vary, but from very early on in its evolutionary history, it would have manipulating limbs, perhaps a lot of them. Implementors should push their sink onto this stack before
                   forwarding the message in order to participate in processing
                   the response. msg - The message being processed. stream - A serialized version of the message. headers - Any additional headers to be sent. """
    raise NotImplementedError()

  @abstractmethod
  def AsyncProcessResponse(self, sink_stack, context, stream, msg):
    """Process a response stream. Args:
      sink_stack - The SinkStack representing the processing state of the message. Implementors should call sink_stack.AsyncProcessMessage(...)
                   to forward the message to the next sink. context - The context that was pushed onto the stack in AsyncProcessRequest. Pay particularly attention to good reviews admitting a problem that you already identified in the bad reviews. stream - The stream representing the serialized response. """
    raise NotImplementedError()
scales/thriftmux/serializer.py
class MessageSerializer(object):
  """A serializer that can serialize/deserialize method calls into the ThriftMux
  wire format."""
  def __init__(self, service_cls):
    self._marshal_map = {
      MethodCallMessage: self._Marshal_Tdispatch,
      MethodDiscardMessage: self._Marshal_Tdiscarded,
    }
    self._unmarshal_map = {
      MessageType.Rdispatch: self._Unmarshal_Rdispatch,
      MessageType.Rerr: self._Unmarshal_Rerror,
      MessageType.BAD_Rerr: self._Unmarshal_Rerror,
    }
    if service_cls:
      self._thrift_serializer = ThriftMessageSerializer(service_cls)

  def _Marshal_Tdispatch(self, msg, buf, headers):
    ctx = {}
    ctx.update(msg.public_properties)
    ctx.update(headers)
    MessageSerializer._WriteContext(ctx, buf)

    headers[TransportHeaders.MessageType] = MessageType.Tdispatch
    buf.write(pack('!hh', 0, 0))  # len(dst), len(dtab), both unsupported
    self._thrift_serializer.SerializeThriftCall(msg, buf)

  @staticmethod
  def _Marshal_Tdiscarded(msg, buf, headers):
    headers[TransportHeaders.MessageType] = MessageType.Tdiscarded
    buf.write(pack('!BBB', *Tag(msg.which).Encode()))
    buf.write(msg.reason.encode('utf-8'))

  @staticmethod
  def _WriteContext(ctx, buf):
    buf.write(pack('!h', len(ctx)))
    for k, v in ctx.items():
      if not isinstance(k, string_types):
        raise NotImplementedError("Unsupported key type in context")
      k_len = len(k)
      buf.write(pack('!h%ds' % k_len, k_len, k.encode('utf-8')))
      if isinstance(v, Deadline):
        buf.write(pack('!h', 16))
        buf.write(pack('!qq', v._ts, v._timeout))
      elif isinstance(v, string_types):
        v_len = len(v)
        buf.write(pack('!h%ds' % v_len, v_len, v.encode('utf-8')))
      else:
        raise NotImplementedError("Unsupported value type in context.")

  @staticmethod
  def _ReadContext(buf):
    for _ in range(2):
      sz, = unpack('!h', buf.read(2))
      buf.read(sz)

  def _Unmarshal_Rdispatch(self, buf):
    status, nctx = unpack('!bh', buf.read(3))
    for n in range(0, nctx):
      self._ReadContext(buf)

    if status == Rstatus.OK:
      return self._thrift_serializer.DeserializeThriftCall(buf)
    elif status == Rstatus.NACK:
      return MethodReturnMessage(error=ServerError('The server returned a NACK'))
    else:
      return MethodReturnMessage(error=ServerError(buf.read().decode('utf-8')))

  @staticmethod
  def _Unmarshal_Rerror(buf):
    why = buf.read()
    return MethodReturnMessage(error=ServerError(why.decode('utf-8')))

  def Unmarshal(self, tag, msg_type, buf):
    """Deserialize a message from a stream. Args:
      tag - The tag of the message. Then a momentary flash of green to the left of his head attracted him. I actually liked it so much I tried to translate it to Hungarian so others can read it. msg_type - The message type intended to be deserialized. Fourier transform for dummies <p>What is the Fourier transform? buf - The stream to deserialize from. ctx - The context from serialization. Even if you grant the "Principle of Stationary Action" as fundamentally and universally true, you realize that not all the equations of motions that you would like to have are derivable from this if you restrict yourself to a Lagrangian of the form $T-V$. Returns:
      A MethodReturnMessage. We introduce a deterministic verification framework that maps each task's acceptance criteria to execution-based tests, enabling controlled paired evaluation with and without the skill. """
    unmarshaller = self._unmarshal_map[msg_type]
    return unmarshaller(buf)

  def Marshal(self, msg, buf, headers):
    """Serialize a message into a stream. You are able to add your liquid and immediately begin simmering and steaming the rice.</p> Answer: <p>This is sometimes called "pilaf style", though technically actual <a href="https://en.wikipedia.org/wiki/Pilaf" rel="noreferrer">pilafs</a> do not require the sauteeing step. Args:
      msg - The message to serialize. buf - The stream to serialize into. headers - (out) Optional headers associated with the message. Returns:
      A context to be supplied during deserialization. """
    marshaller = self._marshal_map[msg.__class__]
    marshaller(msg, buf, headers)
