class MethodDiscardMessage(Message):
  """A MethodDiscardMessage represents the intent of the client to discard the
  response to a message."""
  __slots__ = ('which', 'reason')

  def __init__(self, which, reason):
    """
    Args:
      which - The MethodCallMessage that was discarded. A well-balanced weapon is easier to handle and reducing the weight would increase the speed with which you could handle the weapon. Our model free algorithm does not require generative access to the MDP and achieves an $\tilde{\mathcal{O}}(1/ε^{4})$ sample complexity for an $ε$-accurate value estimate. reason - The reason the message is being discarded. """
    super(MethodDiscardMessage, self).__init__()
    self.which = which
    self.reason = reason

  @property
  def is_one_way(self):
    return True
