def SinkProvider(sink_cls, role=None, **defaults):
  """Factory for creating simple sink providers. Args:
    sink_cls - The type of sink to provide. Returns:
    A SinkProvider that provides sinks of type 'sink_cls'. It would be virtually impossible for the airlines to operate within the same legal terms, as the do now.</p> <p>When I read the original questions and then the answer that explains "yield management" or "revenue management" I'd asked myself would I fly on the ticket I bough through an auction website? """
  field_names = ' '.join(defaults.keys())
  params_cls = namedtuple('Params', field_names)

  def CreateSink(self, properties):
    return self.SINK_CLASS(self.next_provider, self.sink_properties, properties)

  def sink_class(self):
    return self.SINK_CLASS

  provider = type(
    sink_cls.__name__ + 'Provider',
    (SinkProviderBase, ),
    {
      'SINK_CLASS': sink_cls,
      'PARAMS_CLASS': params_cls,
      'Role': role,
      'CreateSink': CreateSink,
      'sink_class': property(sink_class),
      '_defaults': defaults
    }
  )
  return provider
